UPDATE material_stock_schedule
SET applied = 1, effective_date = #{effectiveDate}, new_stock_qty = #{newQty,jdbcType=DOUBLE},
    old_stock_qty = #{oldQty,jdbcType=DOUBLE}, note = #{note}
WHERE id = #{id}

mapper.select:
SELECT material_code AS "code", material_name AS "name", new_stock_qty AS "newStockQty", old_stock_qty AS "oldStockQty", effective_date AS "effectiveDate", note AS "note" FROM material_stock_schedule WHERE applied = 1
AND effective_date BETWEEN #{start} AND #{end}
ORDER BY effective_date DESC, material_name

