INSERT INTO material_warehouse_move (
    material_code, material_name, barcode, from_warehouse_cd, to_warehouse_cd, pack_count, unit_weight, qty, moved_date, moved_by, created_at
) VALUES (
    #{materialCode}, #{materialName}, #{barcode}, (SELECT wh.warehouse_cd FROM tb_warehouse wh WHERE wh.warehouse_nm = #{fromWarehouse} AND wh.factory_code = 'F001' AND wh.plant_code = 'P001' ORDER BY CASE WHEN wh.use_yn = 'Y' THEN 0 ELSE 1 END, wh.warehouse_id LIMIT 1), (SELECT wh.warehouse_cd FROM tb_warehouse wh WHERE wh.warehouse_nm = #{toWarehouse} AND wh.factory_code = 'F001' AND wh.plant_code = 'P001' ORDER BY CASE WHEN wh.use_yn = 'Y' THEN 0 ELSE 1 END, wh.warehouse_id LIMIT 1), #{packCount},
    #{unitWeight,jdbcType=DOUBLE}, #{qty,jdbcType=DOUBLE}, #{movedDate}, #{movedBy}, #{createdAt}
)
